codeExamples.code:
# 1) Create a monthly cost budget of $10,000 with an 80% actual-spend alert
cat > budget.json <<'EOF'
{
  "BudgetName": "data-platform-monthly",
  "BudgetLimit": { "Amount": "10000", "Unit": "USD" },
  "TimeUnit": "MONTHLY",
  "BudgetType": "COST",
  "CostFilters": { "TagKeyValue": ["user:team$data-platform"] }
}
EOF

cat > notifications.json <<'EOF'
[
  {
    "Notification": {
      "NotificationType": "ACTUAL",
      "ComparisonOperator": "GREATER_THAN",
      "Threshold": 80,
      "ThresholdType": "PERCENTAGE"
    },
    "Subscribers": [
      { "SubscriptionType": "EMAIL", "Address": "finops@example.com" }
    ]
  }
]
EOF

aws budgets create-budget \
  --account-id 123456789012 \
  --budget file://budget.json \
  --notifications-with-subscribers file://notifications.json

# 2) Create an anomaly monitor scoped to the whole account, alerting on >$100 impact
aws ce create-anomaly-monitor \
  --anomaly-monitor '{"MonitorName":"account-wide","MonitorType":"DIMENSIONAL","MonitorDimension":"SERVICE"}'

aws ce create-anomaly-subscription \
  --anomaly-subscription '{
    "SubscriptionName":"finops-anomalies",
    "MonitorArnList":["arn:aws:ce::123456789012:anomalymonitor/EXAMPLE"],
    "Subscribers":[{"Type":"EMAIL","Address":"finops@example.com"}],
    "ThresholdExpression":{"Dimensions":{"Key":"ANOMALY_TOTAL_IMPACT_ABSOLUTE","Values":["100"]}},
    "Frequency":"DAILY"
  }'

# lifecycle.json
cat > lifecycle.json <<'EOF'
{
  "Rules": [
    {
      "ID": "tier-raw-data",
      "Filter": { "Prefix": "raw/" },
      "Status": "Enabled",
      "Transitions": [
        { "Days": 30, "StorageClass": "STANDARD_IA" },
        { "Days": 90, "StorageClass": "DEEP_ARCHIVE" }
      ]
    },
    {
      "ID": "expire-temp",
      "Filter": { "Prefix": "tmp/" },
      "Status": "Enabled",
      "Expiration": { "Days": 7 }
    },
    {
      "ID": "cleanup-incomplete-uploads",
      "Filter": {},
      "Status": "Enabled",
      "AbortIncompleteMultipartUpload": { "DaysAfterInitiation": 3 }
    }
  ]
}
EOF

aws s3api put-bucket-lifecycle-configuration \
  --bucket my-data-lake \
  --lifecycle-configuration file://lifecycle.json

# Verify
aws s3api get-bucket-lifecycle-configuration --bucket my-data-lake

